-- Disposable fixture. No material or ledger survives rollback.
begin;
create temporary table material_plans(name text primary key,plan jsonb);grant select,insert,update on material_plans to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
insert into material_plans values('new',public.preview_import_table('00000000-0000-0000-0000-000000000001','materials','[{"code":"MAT_TYPE_TEST","name":"Cáp thử","unit":"m","equipment_category":"QC"}]'));
select test.ok(not exists(select 1 from public.materials where code='MAT_TYPE_TEST'),'preview does not write material category');
select test.ok(public.import_table_batch('00000000-0000-0000-0000-000000000001','materials','add',(select plan from material_plans where name='new'),'73000000-0000-0000-0000-000000000001')=1,'material category created with existing role checks');
select test.ok(public.import_table_batch('00000000-0000-0000-0000-000000000001','materials','add',(select plan from material_plans where name='new'),'73000000-0000-0000-0000-000000000001')=1,'manual-style save retry is idempotent');
select test.ok((select count(*)=1 from public.materials where code='MAT_TYPE_TEST'),'retry creates one material only');
select test.ok((select equipment_category='QC' and minimum_stock=0 and service_limit_hours is null from public.materials where code='MAT_TYPE_TEST'),'category does not invent stock or life limit');
select test.fails($q$select public.preview_import_table('00000000-0000-0000-0000-000000000001','materials','[{"code":"MAT_BAD","name":"Thử","unit":"m","equipment_category":"WRONG"}]')$q$,'22023','invalid category rejected');
select test.fails($q$update public.materials set equipment_category='WRONG' where code='MAT_TYPE_TEST'$q$,'23514','table constraint also enforces category');
insert into material_plans values('stale',public.preview_import_table('00000000-0000-0000-0000-000000000001','materials','[{"code":"MAT_TYPE_TEST","name":"Cáp sửa","unit":"m","equipment_category":"RTG"}]'));
update public.materials set equipment_category='COMMON' where code='MAT_TYPE_TEST';
select test.fails($q$select public.import_table_batch('00000000-0000-0000-0000-000000000001','materials','replace',(select plan from material_plans where name='stale'),gen_random_uuid())$q$,'40001','category snapshot prevents overwriting a newer change');
insert into material_plans values('legacy',public.preview_import_table('00000000-0000-0000-0000-000000000001','materials','[{"code":"MAT_TYPE_TEST","name":"Tên từ tệp cũ","unit":"m"}]'));
select public.import_table_batch('00000000-0000-0000-0000-000000000001','materials','replace',(select plan from material_plans where name='legacy'),gen_random_uuid());
select test.ok((select equipment_category='COMMON' from public.materials where code='MAT_TYPE_TEST'),'legacy three-column file preserves existing category');
insert into material_plans values('unknown',public.preview_import_table('00000000-0000-0000-0000-000000000001','materials','[{"code":"MAT_TYPE_TEST","name":"Chưa rõ loại","unit":"m","equipment_category":null}]'));
select public.import_table_batch('00000000-0000-0000-0000-000000000001','materials','replace',(select plan from material_plans where name='unknown'),gen_random_uuid());
select test.ok((select equipment_category is null from public.materials where code='MAT_TYPE_TEST'),'unknown category stays null, distinct from common');
select test.fails($q$select public.preview_import_table('00000000-0000-0000-0000-000000000001','materials','[{"code":"MAT_TYPE_TEST","name":"Thử","unit":"bộ","equipment_category":null}]')$q$,'22023','unit remains immutable');
select test.fails($q$select public.import_table_batch('00000000-0000-0000-0000-000000000001','materials','add','[{"row":{"code":"MAT_PARTIAL","name":"Thử","unit":"bộ","equipment_category":"QC"},"expected":null},{"row":{"code":"MAT_BAD","name":"Thử","unit":"bộ","equipment_category":"WRONG"},"expected":null}]',gen_random_uuid())$q$,'22023','one bad category aborts batch');
select test.ok(not exists(select 1 from public.materials where code='MAT_PARTIAL'),'no partial material from failed batch');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select test.ok(jsonb_array_length(public.preview_import_table('00000000-0000-0000-0000-000000000001','materials','[{"code":"SUPPLY_TYPE","name":"Thử","unit":"bộ","equipment_category":"RTG"}]'))=1,'supply may prepare category import');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select test.fails($q$select public.preview_import_table('00000000-0000-0000-0000-000000000001','materials','[{"code":"TECH_TYPE","name":"Thử","unit":"bộ","equipment_category":"QC"}]')$q$,'42501','technician cannot write material category');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000005',true);
select test.fails($q$select public.preview_import_table('00000000-0000-0000-0000-000000000001','materials','[{"code":"FOREIGN_TYPE","name":"Thử","unit":"bộ","equipment_category":null}]')$q$,'42501','foreign leader cannot prepare category import');
reset role;
select test.ok((select count(*)=2 from pg_proc where oid in ('public.preview_import_table(uuid,text,jsonb)'::regprocedure,'public.import_table_batch(uuid,text,text,jsonb,uuid)'::regprocedure) and not prosecdef),'updated public functions remain invoker');
rollback;
